-- v3 of the gma_pattern pilot, 2026-08-01 session (Peter feedback):
-- (1) v2's tier 3 wasn't hard enough per CJS(1990)'s own difficulty ranking -- their
--     hardest single rule type, distribution-of-two, was unused. Added item 9
--     (distribution-of-two + progression) and item 10, a true ceiling item stacking
--     3 concurrent rules across 3 attributes, matching how genuinely hard
--     matrix-reasoning items (and RAVEN/PGM-generator literature) are constructed.
-- (2) v2's item 6 stacked a rotation rule onto circle/square, both of which have
--     rotational symmetry that makes rotation invisible at 90-degree steps. Rebuilt
--     using triangle/right-triangle/arrow -- three shapes with no such symmetry --
--     so the rotation dimension is now visible in every cell.
-- (3) Own-QA catch: the rebuilt item 6 initially had duplicate distractors (options
--     A and E were identical). Added a duplicate-options assertion to the generator's
--     verification pass so this can't recur for any future item.
-- Bank now spans tiers 1-4, 10 items total (was 8).

DELETE FROM public.hiregauge_instrument_items
WHERE cognitive_domain = 'gma_pattern' AND stint = 0 AND is_active = false;

INSERT INTO public.hiregauge_instrument_items (item_number, item_text, choices, answer_key, notes, stint, is_active, cognitive_domain, section) VALUES
(1, 'Shape steps circle→square→triangle left to right; same order in every row.', '{"grid": [{"fill": "solid", "size": "m", "count": 1, "shape": "circle", "rotation": 0}, {"fill": "solid", "size": "m", "count": 1, "shape": "square", "rotation": 0}, {"fill": "solid", "size": "m", "count": 1, "shape": "triangle", "rotation": 0}, {"fill": "solid", "size": "m", "count": 1, "shape": "circle", "rotation": 0}, {"fill": "solid", "size": "m", "count": 1, "shape": "square", "rotation": 0}, {"fill": "solid", "size": "m", "count": 1, "shape": "triangle", "rotation": 0}, {"fill": "solid", "size": "m", "count": 1, "shape": "circle", "rotation": 0}, {"fill": "solid", "size": "m", "count": 1, "shape": "square", "rotation": 0}, null], "options": {"A": {"fill": "solid", "size": "m", "count": 2, "shape": "triangle", "rotation": 0}, "B": {"fill": "solid", "size": "m", "count": 1, "shape": "square", "rotation": 0}, "C": {"fill": "solid", "size": "m", "count": 1, "shape": "circle", "rotation": 0}, "D": {"fill": "solid", "size": "m", "count": 1, "shape": "triangle", "rotation": 90}, "E": {"fill": "solid", "size": "m", "count": 1, "shape": "hexagon", "rotation": 0}, "F": {"fill": "solid", "size": "m", "count": 1, "shape": "triangle", "rotation": 0}}}'::jsonb, 'F', 'pattern_1_tier1_v3', 0, false, 'gma_pattern', 'newtworks_v2_cognitive_gma'),
(2, 'Triangle rotates 0°→90°→180° left to right; same order in every row. (Triangle has no 90°/180° rotational symmetry, so the rotation is genuinely visible.)', '{"grid": [{"fill": "solid", "size": "m", "count": 1, "shape": "triangle", "rotation": 0}, {"fill": "solid", "size": "m", "count": 1, "shape": "triangle", "rotation": 90}, {"fill": "solid", "size": "m", "count": 1, "shape": "triangle", "rotation": 180}, {"fill": "solid", "size": "m", "count": 1, "shape": "triangle", "rotation": 0}, {"fill": "solid", "size": "m", "count": 1, "shape": "triangle", "rotation": 90}, {"fill": "solid", "size": "m", "count": 1, "shape": "triangle", "rotation": 180}, {"fill": "solid", "size": "m", "count": 1, "shape": "triangle", "rotation": 0}, {"fill": "solid", "size": "m", "count": 1, "shape": "triangle", "rotation": 90}, null], "options": {"A": {"fill": "solid", "size": "m", "count": 1, "shape": "triangle", "rotation": 270}, "B": {"fill": "solid", "size": "m", "count": 1, "shape": "triangle", "rotation": 90}, "C": {"fill": "solid", "size": "m", "count": 1, "shape": "triangle", "rotation": 0}, "D": {"fill": "solid", "size": "m", "count": 2, "shape": "triangle", "rotation": 180}, "E": {"fill": "solid", "size": "m", "count": 1, "shape": "square", "rotation": 180}, "F": {"fill": "solid", "size": "m", "count": 1, "shape": "triangle", "rotation": 180}}}'::jsonb, 'F', 'pattern_2_tier1_v3', 0, false, 'gma_pattern', 'newtworks_v2_cognitive_gma'),
(3, 'Every row contains circle, square, and triangle exactly once — order re-shuffled each row (elimination, not sequence).', '{"grid": [{"fill": "solid", "size": "m", "count": 1, "shape": "circle", "rotation": 0}, {"fill": "solid", "size": "m", "count": 1, "shape": "square", "rotation": 0}, {"fill": "solid", "size": "m", "count": 1, "shape": "triangle", "rotation": 0}, {"fill": "solid", "size": "m", "count": 1, "shape": "square", "rotation": 0}, {"fill": "solid", "size": "m", "count": 1, "shape": "triangle", "rotation": 0}, {"fill": "solid", "size": "m", "count": 1, "shape": "circle", "rotation": 0}, {"fill": "solid", "size": "m", "count": 1, "shape": "triangle", "rotation": 0}, {"fill": "solid", "size": "m", "count": 1, "shape": "circle", "rotation": 0}, null], "options": {"A": {"fill": "solid", "size": "m", "count": 1, "shape": "triangle", "rotation": 0}, "B": {"fill": "solid", "size": "m", "count": 1, "shape": "circle", "rotation": 0}, "C": {"fill": "solid", "size": "m", "count": 2, "shape": "square", "rotation": 0}, "D": {"fill": "solid", "size": "m", "count": 1, "shape": "hexagon", "rotation": 0}, "E": {"fill": "solid", "size": "m", "count": 1, "shape": "square", "rotation": 90}, "F": {"fill": "solid", "size": "m", "count": 1, "shape": "square", "rotation": 0}}}'::jsonb, 'F', 'pattern_3_tier2_v3', 0, false, 'gma_pattern', 'newtworks_v2_cognitive_gma'),
(4, 'Every row contains outline, solid, and striped fill exactly once — order re-shuffled each row.', '{"grid": [{"fill": "outline", "size": "m", "count": 1, "shape": "circle", "rotation": 0}, {"fill": "solid", "size": "m", "count": 1, "shape": "circle", "rotation": 0}, {"fill": "striped", "size": "m", "count": 1, "shape": "circle", "rotation": 0}, {"fill": "solid", "size": "m", "count": 1, "shape": "circle", "rotation": 0}, {"fill": "striped", "size": "m", "count": 1, "shape": "circle", "rotation": 0}, {"fill": "outline", "size": "m", "count": 1, "shape": "circle", "rotation": 0}, {"fill": "striped", "size": "m", "count": 1, "shape": "circle", "rotation": 0}, {"fill": "outline", "size": "m", "count": 1, "shape": "circle", "rotation": 0}, null], "options": {"A": {"fill": "striped", "size": "m", "count": 1, "shape": "circle", "rotation": 0}, "B": {"fill": "outline", "size": "m", "count": 1, "shape": "circle", "rotation": 0}, "C": {"fill": "solid", "size": "m", "count": 2, "shape": "circle", "rotation": 0}, "D": {"fill": "solid", "size": "m", "count": 1, "shape": "square", "rotation": 0}, "E": {"fill": "solid", "size": "m", "count": 1, "shape": "circle", "rotation": 90}, "F": {"fill": "solid", "size": "m", "count": 1, "shape": "circle", "rotation": 0}}}'::jsonb, 'F', 'pattern_4_tier2_v3', 0, false, 'gma_pattern', 'newtworks_v2_cognitive_gma'),
(5, 'Every row contains small, medium, and large exactly once — order re-shuffled each row.', '{"grid": [{"fill": "solid", "size": "s", "count": 1, "shape": "square", "rotation": 0}, {"fill": "solid", "size": "m", "count": 1, "shape": "square", "rotation": 0}, {"fill": "solid", "size": "l", "count": 1, "shape": "square", "rotation": 0}, {"fill": "solid", "size": "m", "count": 1, "shape": "square", "rotation": 0}, {"fill": "solid", "size": "l", "count": 1, "shape": "square", "rotation": 0}, {"fill": "solid", "size": "s", "count": 1, "shape": "square", "rotation": 0}, {"fill": "solid", "size": "l", "count": 1, "shape": "square", "rotation": 0}, {"fill": "solid", "size": "s", "count": 1, "shape": "square", "rotation": 0}, null], "options": {"A": {"fill": "solid", "size": "l", "count": 1, "shape": "square", "rotation": 0}, "B": {"fill": "solid", "size": "s", "count": 1, "shape": "square", "rotation": 0}, "C": {"fill": "solid", "size": "m", "count": 2, "shape": "square", "rotation": 0}, "D": {"fill": "solid", "size": "m", "count": 1, "shape": "triangle", "rotation": 0}, "E": {"fill": "solid", "size": "m", "count": 1, "shape": "square", "rotation": 90}, "F": {"fill": "solid", "size": "m", "count": 1, "shape": "square", "rotation": 0}}}'::jsonb, 'F', 'pattern_5_tier2_v3', 0, false, 'gma_pattern', 'newtworks_v2_cognitive_gma'),
(6, 'FIXED: shape is triangle/right-triangle/arrow once per row (elimination, reshuffled) AND rotation steps 0°→90°→180° by column. All three shapes are rotationally asymmetric, so the rotation dimension is visible in every cell (unlike v2, which used circle/square).', '{"grid": [{"fill": "solid", "size": "m", "count": 1, "shape": "triangle", "rotation": 0}, {"fill": "solid", "size": "m", "count": 1, "shape": "rightTriangle", "rotation": 90}, {"fill": "solid", "size": "m", "count": 1, "shape": "arrow", "rotation": 180}, {"fill": "solid", "size": "m", "count": 1, "shape": "rightTriangle", "rotation": 0}, {"fill": "solid", "size": "m", "count": 1, "shape": "arrow", "rotation": 90}, {"fill": "solid", "size": "m", "count": 1, "shape": "triangle", "rotation": 180}, {"fill": "solid", "size": "m", "count": 1, "shape": "arrow", "rotation": 0}, {"fill": "solid", "size": "m", "count": 1, "shape": "triangle", "rotation": 90}, null], "options": {"A": {"fill": "solid", "size": "m", "count": 1, "shape": "rightTriangle", "rotation": 90}, "B": {"fill": "solid", "size": "m", "count": 1, "shape": "triangle", "rotation": 180}, "C": {"fill": "solid", "size": "m", "count": 2, "shape": "rightTriangle", "rotation": 180}, "D": {"fill": "solid", "size": "m", "count": 1, "shape": "hexagon", "rotation": 180}, "E": {"fill": "solid", "size": "m", "count": 1, "shape": "triangle", "rotation": 90}, "F": {"fill": "solid", "size": "m", "count": 1, "shape": "rightTriangle", "rotation": 180}}}'::jsonb, 'F', 'pattern_6_tier3_v3', 0, false, 'gma_pattern', 'newtworks_v2_cognitive_gma'),
(7, 'Two rules at once: size is small/medium/large once per row (elimination, reshuffled) AND fill is constant within a row, changing outline→solid→striped row to row.', '{"grid": [{"fill": "outline", "size": "s", "count": 1, "shape": "circle", "rotation": 0}, {"fill": "outline", "size": "m", "count": 1, "shape": "circle", "rotation": 0}, {"fill": "outline", "size": "l", "count": 1, "shape": "circle", "rotation": 0}, {"fill": "solid", "size": "m", "count": 1, "shape": "circle", "rotation": 0}, {"fill": "solid", "size": "l", "count": 1, "shape": "circle", "rotation": 0}, {"fill": "solid", "size": "s", "count": 1, "shape": "circle", "rotation": 0}, {"fill": "striped", "size": "l", "count": 1, "shape": "circle", "rotation": 0}, {"fill": "striped", "size": "s", "count": 1, "shape": "circle", "rotation": 0}, null], "options": {"A": {"fill": "solid", "size": "m", "count": 1, "shape": "circle", "rotation": 0}, "B": {"fill": "striped", "size": "l", "count": 1, "shape": "circle", "rotation": 0}, "C": {"fill": "striped", "size": "m", "count": 2, "shape": "circle", "rotation": 0}, "D": {"fill": "striped", "size": "m", "count": 1, "shape": "square", "rotation": 0}, "E": {"fill": "outline", "size": "s", "count": 1, "shape": "circle", "rotation": 0}, "F": {"fill": "striped", "size": "m", "count": 1, "shape": "circle", "rotation": 0}}}'::jsonb, 'F', 'pattern_7_tier3_v3', 0, false, 'gma_pattern', 'newtworks_v2_cognitive_gma'),
(8, 'Two rules at once: shape is circle/square/triangle once per row (elimination, reshuffled) AND the third column''s count equals the sum of the first two columns'' counts.', '{"grid": [{"fill": "solid", "size": "m", "count": 1, "shape": "circle", "rotation": 0}, {"fill": "solid", "size": "m", "count": 1, "shape": "square", "rotation": 0}, {"fill": "solid", "size": "m", "count": 2, "shape": "triangle", "rotation": 0}, {"fill": "solid", "size": "m", "count": 1, "shape": "square", "rotation": 0}, {"fill": "solid", "size": "m", "count": 2, "shape": "triangle", "rotation": 0}, {"fill": "solid", "size": "m", "count": 3, "shape": "circle", "rotation": 0}, {"fill": "solid", "size": "m", "count": 2, "shape": "triangle", "rotation": 0}, {"fill": "solid", "size": "m", "count": 1, "shape": "circle", "rotation": 0}, null], "options": {"A": {"fill": "solid", "size": "m", "count": 2, "shape": "square", "rotation": 0}, "B": {"fill": "solid", "size": "m", "count": 3, "shape": "triangle", "rotation": 0}, "C": {"fill": "solid", "size": "m", "count": 4, "shape": "square", "rotation": 0}, "D": {"fill": "solid", "size": "m", "count": 3, "shape": "circle", "rotation": 0}, "E": {"fill": "solid", "size": "m", "count": 3, "shape": "hexagon", "rotation": 0}, "F": {"fill": "solid", "size": "m", "count": 3, "shape": "square", "rotation": 0}}}'::jsonb, 'F', 'pattern_8_tier3_v3', 0, false, 'gma_pattern', 'newtworks_v2_cognitive_gma'),
(9, 'Two rules at once: fill only ever takes 2 values (solid/striped) — each row has one value twice and the other once, and which value is doubled ALTERNATES row to row (must be tracked by counting occurrences, not by following a left-to-right sequence) — AND size steps small→medium→large by column.', '{"grid": [{"fill": "solid", "size": "s", "count": 1, "shape": "circle", "rotation": 0}, {"fill": "solid", "size": "m", "count": 1, "shape": "circle", "rotation": 0}, {"fill": "striped", "size": "l", "count": 1, "shape": "circle", "rotation": 0}, {"fill": "striped", "size": "s", "count": 1, "shape": "circle", "rotation": 0}, {"fill": "striped", "size": "m", "count": 1, "shape": "circle", "rotation": 0}, {"fill": "solid", "size": "l", "count": 1, "shape": "circle", "rotation": 0}, {"fill": "solid", "size": "s", "count": 1, "shape": "circle", "rotation": 0}, {"fill": "solid", "size": "m", "count": 1, "shape": "circle", "rotation": 0}, null], "options": {"A": {"fill": "solid", "size": "l", "count": 1, "shape": "circle", "rotation": 0}, "B": {"fill": "striped", "size": "m", "count": 1, "shape": "circle", "rotation": 0}, "C": {"fill": "striped", "size": "l", "count": 2, "shape": "circle", "rotation": 0}, "D": {"fill": "striped", "size": "l", "count": 1, "shape": "square", "rotation": 0}, "E": {"fill": "outline", "size": "l", "count": 1, "shape": "circle", "rotation": 0}, "F": {"fill": "striped", "size": "l", "count": 1, "shape": "circle", "rotation": 0}}}'::jsonb, 'F', 'pattern_9_tier4_v3', 0, false, 'gma_pattern', 'newtworks_v2_cognitive_gma'),
(10, 'Three independent rules tracked at once: shape (circle/square/triangle, once per row, reshuffled) + count (3rd column = sum of first two) + fill (2 values only, one doubled per row, alternating which one). This is the genuine ceiling item — matches how the hardest real matrix-reasoning items combine 3+ concurrent rules across different attributes, not just 2.', '{"grid": [{"fill": "outline", "size": "m", "count": 1, "shape": "circle", "rotation": 0}, {"fill": "outline", "size": "m", "count": 1, "shape": "square", "rotation": 0}, {"fill": "solid", "size": "m", "count": 2, "shape": "triangle", "rotation": 0}, {"fill": "solid", "size": "m", "count": 1, "shape": "square", "rotation": 0}, {"fill": "solid", "size": "m", "count": 2, "shape": "triangle", "rotation": 0}, {"fill": "outline", "size": "m", "count": 3, "shape": "circle", "rotation": 0}, {"fill": "outline", "size": "m", "count": 2, "shape": "triangle", "rotation": 0}, {"fill": "outline", "size": "m", "count": 1, "shape": "circle", "rotation": 0}, null], "options": {"A": {"fill": "outline", "size": "m", "count": 3, "shape": "square", "rotation": 0}, "B": {"fill": "solid", "size": "m", "count": 3, "shape": "triangle", "rotation": 0}, "C": {"fill": "solid", "size": "m", "count": 2, "shape": "square", "rotation": 0}, "D": {"fill": "solid", "size": "m", "count": 3, "shape": "hexagon", "rotation": 0}, "E": {"fill": "outline", "size": "m", "count": 4, "shape": "square", "rotation": 0}, "F": {"fill": "solid", "size": "m", "count": 3, "shape": "square", "rotation": 0}}}'::jsonb, 'F', 'pattern_10_tier4_v3', 0, false, 'gma_pattern', 'newtworks_v2_cognitive_gma');
